                ctx.var("$@jupeelevatorinuse2").set(Val::from(0))?;
                ctx.call(Function::DoNpcEvent, vec![Val::from("TimeOut#ufe::OnEnable")])?;
                ctx.call(Function::DoNpcEvent, vec![Val::from("Guard-1#ufe::OnEnable")])?;
