#[derive(Clone, Copy, Debug)]
enum Guard3UfeStep {
    Start,
    OnEnable,
    OnDisable,
    OnTimer2000,
    OnTimer5000,
    OnTimer8000,
    OnTimer12000,
    OnTimer30000,
    OnMyMobDead,
}

fn guard_3_ufe_run(ctx: &Ctx, mut step: Guard3UfeStep, args: Vec<Val>) -> Result<Val, Stop> {
    'machine: loop {
        match step {
            Guard3UfeStep::Start => {
                step = Guard3UfeStep::OnEnable;
                continue 'machine;
            }
            Guard3UfeStep::OnEnable => {
                ctx.call(Function::InitNpcTimer, vec![])?;
                return Err(Stop::End);
            }
            Guard3UfeStep::OnDisable => {
                ctx.call(Function::StopNpcTimer, vec![])?;
                return Err(Stop::End);
            }
            Guard3UfeStep::OnTimer2000 => {
                ctx.call(
                    Function::MapAnnounce,
                    vec![
                        Val::from("jupe_ele"),
                        Val::from("What do you see?"),
                        ctx.constant("BC_MAP")?,
                        Val::from("0xFF0000"),
                    ],
                )?;
                return Err(Stop::End);
            }
            Guard3UfeStep::OnTimer5000 => {
                ctx.call(
                    Function::MapAnnounce,
                    vec![
                        Val::from("jupe_ele"),
                        Val::from("Are your eyes actually seeing something?"),
                        ctx.constant("BC_MAP")?,
                        Val::from("0xFF0000"),
                    ],
                )?;
                return Err(Stop::End);
            }
            Guard3UfeStep::OnTimer8000 => {
                ctx.call(
                    Function::MapAnnounce,
                    vec![
                        Val::from("jupe_ele"),
                        Val::from("Or do you just believe you are seeing?"),
                        ctx.constant("BC_MAP")?,
                        Val::from("0xFF0000"),
                    ],
                )?;
                return Err(Stop::End);
            }
            Guard3UfeStep::OnTimer12000 => {
                ctx.var(".mymobs").set(Val::from(8))?;
                ctx.call(
                    Function::Monster,
                    vec![
                        Val::from("jupe_ele"),
                        Val::from(48),
                        Val::from(44),
                        Val::from("Guard"),
                        Val::from(1675),
                        Val::from(1),
                        Val::from("Guard-3#ufe::OnMyMobDead"),
                    ],
                )?;
                ctx.call(
                    Function::Monster,
                    vec![
                        Val::from("jupe_ele"),
                        Val::from(45),
                        Val::from(42),
                        Val::from("Guard"),
                        Val::from(1669),
                        Val::from(1),
                        Val::from("Guard-3#ufe::OnMyMobDead"),
                    ],
                )?;
                ctx.call(
                    Function::Monster,
                    vec![
                        Val::from("jupe_ele"),
                        Val::from(38),
                        Val::from(42),
                        Val::from("Guard"),
                        Val::from(1683),
                        Val::from(1),
                        Val::from("Guard-3#ufe::OnMyMobDead"),
                    ],
                )?;
                ctx.call(
                    Function::Monster,
                    vec![
                        Val::from("jupe_ele"),
                        Val::from(35),
                        Val::from(44),
                        Val::from("Guard"),
                        Val::from(1675),
                        Val::from(1),
                        Val::from("Guard-3#ufe::OnMyMobDead"),
                    ],
                )?;
                ctx.call(
                    Function::Monster,
                    vec![
                        Val::from("jupe_ele"),
                        Val::from(35),
                        Val::from(51),
                        Val::from("Guard"),
                        Val::from(1669),
                        Val::from(1),
                        Val::from("Guard-3#ufe::OnMyMobDead"),
                    ],
                )?;
                ctx.call(
                    Function::Monster,
                    vec![
                        Val::from("jupe_ele"),
                        Val::from(38),
                        Val::from(53),
                        Val::from("Guard"),
                        Val::from(1683),
                        Val::from(1),
                        Val::from("Guard-3#ufe::OnMyMobDead"),
                    ],
                )?;
                ctx.call(
                    Function::Monster,
                    vec![
                        Val::from("jupe_ele"),
                        Val::from(45),
                        Val::from(53),
                        Val::from("Guard"),
                        Val::from(1675),
                        Val::from(1),
                        Val::from("Guard-3#ufe::OnMyMobDead"),
                    ],
                )?;
                ctx.call(
                    Function::Monster,
                    vec![
                        Val::from("jupe_ele"),
                        Val::from(48),
                        Val::from(51),
                        Val::from("Guard"),
                        Val::from(1669),
                        Val::from(1),
                        Val::from("Guard-3#ufe::OnMyMobDead"),
                    ],
                )?;
                ctx.var("$@jupeelevatorinuse2").set(Val::from(3))?;
                return Err(Stop::End);
            }
            Guard3UfeStep::OnTimer30000 => {
                if ctx.var("$@jupeelevatorinuse2").get()? == 3 {
                    ctx.call(Function::DoNpcEvent, vec![Val::from("Guard-4#ufe::OnEnable")])?;
                    ctx.call(Function::StopNpcTimer, vec![])?;
                }
                return Err(Stop::End);
            }
            Guard3UfeStep::OnMyMobDead => {
                ctx.var(".mymobs").set((ctx.var(".mymobs").get()?.try_sub(Val::from(1))?))?;
                if ctx.var(".mymobs").get()?.number()? < 1 {
                    if ctx.var("$@jupeelevatorinuse2").get()? == 3 {
                        ctx.call(Function::DoNpcEvent, vec![Val::from("Guard-4#ufe::OnEnable")])?;
                        ctx.call(Function::StopNpcTimer, vec![])?;
                    } else {
                        if (((ctx.var("$@jupeelevatorinuse2").get()? == 4
                            && ctx
                                .call(
                                    Function::GetVariableOfNpc,
                                    vec![Val::from(".mymobs"), Val::from("Guard-1#ufe"), Val::from(0)],
                                )?
                                .number()?
                                < 1)
                            && ctx
                                .call(
                                    Function::GetVariableOfNpc,
                                    vec![Val::from(".mymobs"), Val::from("Guard-2#ufe"), Val::from(0)],
                                )?
                                .number()?
                                < 1)
                            && ctx
                                .call(
                                    Function::GetVariableOfNpc,
                                    vec![Val::from(".mymobs"), Val::from("Guard-4#ufe"), Val::from(0)],
                                )?
                                .number()?
                                < 1)
                        {
                            ctx.call(Function::DoNpcEvent, vec![Val::from("GuardEnd#ufe::OnEnable")])?;
                            ctx.call(Function::StopNpcTimer, vec![])?;
                        }
                    }
                }
                return Err(Stop::End);
            }
        }
    }
}

